    #[serde(default)]
    pub supports_checkpoints: bool,
    /// Whether the plugin supports state verification.
    #[serde(default)]
    pub supports_verification: bool,
    /// Whether the plugin's operations are atomic.
    #[serde(default)]
    pub atomic_operations: bool,
}

